'use strict';
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=v=>v?new Date(v).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}):'—';
const percent=r=>r.score===null?'—':Math.round(r.score/r.total_points*100);
let authEpoch=0;
let user=null,csrf='',registering=false,page='overview',exams=[],results=[],users=[],attempt=null,answerMap={},timer=null,saveTimer=null,clockOffset=0,saving=Promise.resolve(),questionExam=null,questions=[],busy=false;
const typeLabels={multiple_choice:'Multiple choice',true_false:'True / false',identification:'Identification',enumeration:'Enumeration',mixed:'Mixed (all four types)'};
const qType=q=>q.question_type||(q.options?.length===2?'true_false':'multiple_choice');
const isText=q=>['identification','enumeration'].includes(qType(q));
function typeOptions(selected,mixed=false){return Object.entries(typeLabels).filter(([t])=>mixed||t!=='mixed').map(([t,n])=>`<option value="${t}" ${t===selected?'selected':''}>${n}</option>`).join('');}
function keyText(q){return(q.accepted_answers||[]).map(g=>g.join(' | ')).join('\n');}
function parseKey(v){return String(v||'').split(/\r?\n/).filter(x=>x.trim()).map(line=>line.split('|').map(x=>x.trim()).filter(Boolean));}
function keyFields(q,suffix=''){return `<label>${qType(q)==='enumeration'?'Required items: one item per line':'Accepted answer: one line'}<textarea name="key${suffix}" required maxlength="12000" placeholder="${qType(q)==='enumeration'?'HTML | Hypertext Markup Language\nCSS | Cascading Style Sheets\nJavaScript | JS':'HTML | Hypertext Markup Language'}">${esc(keyText(q))}</textarea></label><p class="note">Separate accepted spellings of the same item with |. Matching ignores case and extra spaces. ${qType(q)==='enumeration'?'Items can be answered in any order. All required items must match for full points; duplicates do not count.':'Keep all acceptable spellings on one line.'}</p>`;}
function instructorKey(q){return isText(q)?`<p class="fine muted">${esc(typeLabels[qType(q)])} · ${qType(q)==='enumeration'?q.accepted_answers.length+' required items':''}</p><ol>${q.accepted_answers.map(g=>`<li>${g.map(esc).join(' / ')}</li>`).join('')}</ol>`:q.options.map((o,j)=>`<div class="option ${j===q.correct_index?'correct':''}"><b>${String.fromCharCode(65+j)}.</b><span>${esc(o)} ${j===q.correct_index?'✓':''}</span></div>`).join('');}
function studentFields(q){if(qType(q)==='identification')return `<label>Your answer<input type="text" maxlength="500" data-question="${q.id}" value="${esc(answerMap[q.id]||'')}" autocomplete="off"></label><p class="fine muted">Capitalization and extra spaces are ignored.</p>`;if(qType(q)==='enumeration')return `<p class="note">Enter ${q.item_count} distinct items, in any order. All items must be correct for full points.</p>${Array.from({length:q.item_count},(_,i)=>`<label>Item ${i+1}<input type="text" maxlength="500" data-question="${q.id}" data-item="${i}" value="${esc(answerMap[q.id]?.[i]||'')}" autocomplete="off"></label>`).join('')}`;return q.options.map((o,j)=>`<label class="option"><input type="radio" name="q${q.id}" data-question="${q.id}" value="${j}" ${answerMap[q.id]===j?'checked':''}><span><b>${String.fromCharCode(65+j)}.</b> ${esc(o)}</span></label>`).join('');}
function hasAnswer(v){return Number.isInteger(v)||typeof v==='string'&&!!v.trim()||Array.isArray(v)&&v.some(x=>x.trim());}
function answerCount(){return Object.values(answerMap).filter(hasAnswer).length;}
function readStudentAnswer(el){if(!attempt||busy)return;const q=attempt.questions.find(q=>String(q.id)===el.dataset.question);if(!q)return;if(qType(q)==='enumeration'){const v=Array.isArray(answerMap[q.id])?[...answerMap[q.id]]:Array(q.item_count).fill('');v[Number(el.dataset.item)]=el.value;answerMap[q.id]=v;}else answerMap[q.id]=isText(q)?el.value:Number(el.value);updateProgress();}

let toastTimer;
function toast(s,error=false){$('toast').textContent=s;$('toast').className=error?'error':'';$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,6000);}
async function api(url,method='GET',body){const epoch=authEpoch;if(method!=='GET'&&!csrf)csrf=(await api('/csrf')).token;const opts={method,credentials:'same-origin'};if(method!=='GET'){opts.headers={'Content-Type':'application/json','X-CSRF-Token':csrf};opts.body=JSON.stringify(body??{});}const r=await fetch('/api'+url,opts);const d=await r.json();if(epoch!==authEpoch)throw Error('Session changed.');if(!r.ok){const e=Error(d.message||'Request failed.');e.status=r.status;throw e;}if(d.token)csrf=d.token;return d;}
function badge(s){return `<span class="badge ${esc(s)}">${esc(s.replaceAll('_',' '))}</span>`;}
function heading(title,description,action=''){return `<div class="page-heading"><div><span class="eyebrow">${esc(user.role)} WORKSPACE</span><h1>${esc(title)}</h1><p class="muted">${esc(description)}</p></div>${action}</div>`;}
function stat(label,value,detail,icon="exams"){
 const paths={exams:'<path d="M7 3h7l5 5v13H7zM14 3v5h5M10 12h6M10 16h6"/>',completed:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',score:'<rect x="4" y="12" width="4" height="8" rx="1"/><rect x="10" y="8" width="4" height="12" rx="1"/><rect x="16" y="4" width="4" height="16" rx="1"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>'};
 const iconSvg=`<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${paths[icon]||paths.exams}</svg>`;
 return `<article class="stat"><span class="stat-icon" aria-hidden="true">${iconSvg}</span><div class="stat-content"><small>${esc(label)}</small><b>${esc(value)}</b><span>${esc(detail)}</span></div></article>`;}
function overviewExamCard(e){
 const student=user.role==='student';if(!student)return examCard(e);
 const now=Date.now(),available=(!e.opens_at||new Date(e.opens_at)<=now)&&(!e.closes_at||new Date(e.closes_at)>now);
 const icon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 8h6M9 12h6M9 16h4"/></svg>';
 const sub=`${esc(e.sample_count||e.question_count)} questions · ${esc(e.duration_minutes)} min`;
 const due=e.closes_at?`Due: ${esc(date(e.closes_at))}`:'No closing date set';
 const action=e.active_attempt_id?'Resume examination →':!available?'Outside scheduled time':e.used_attempts>=e.max_attempts?'Attempt limit reached':'Start Exam →';
 return `<article class="exam-card"><div>${badge(e.status)} <span class="muted fine">#${e.id}</span></div><div class="exam-card-title-row"><span class="exam-art">${icon}</span><div><h3>${esc(e.title)}</h3><p class="description">${sub}</p><p class="exam-card-overview-meta">${due}</p></div></div><div class="actions"><button class="primary" data-action="start" data-id="${e.id}" ${!e.active_attempt_id&&(!available||e.used_attempts>=e.max_attempts)?'disabled':''}>${action}</button></div></article>`;
}
function empty(s){return `<div class="empty">${esc(s)}</div>`;}
function showAuth(){stopExam();user=null;$('shell').hidden=true;$('auth').hidden=false;}
function setupShell(){ $('auth').hidden=true;$('shell').hidden=false;$('sidebar-name').textContent=user.full_name;$('sidebar-role').textContent=user.role;$('initials').textContent=user.full_name.split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase();$('topbar-initials').textContent=$('initials').textContent;$('topbar-name').textContent=user.full_name;$('topbar-role').textContent=user.role;const nav=[['overview','▦','Overview'],['exams','▤',user.role==='student'?'Available Exams':'Examinations'],['results','▥',user.role==='student'?'My Results':'Results & Reports'],...(user.role==='student'?[['classes','♧','My Classes']]:[['students','♙','Students'],['classes','♧','Classes & Sections'],['bank','▧','Question Bank']]),...(user.role==='admin'?[['users','♙','Users'],['audit','◷','Activity Log']]:[]),['profile','⚙','Profile'],['signout','↪','Sign Out']];const navPaths={overview:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',exams:'<rect x="5" y="5" width="14" height="16" rx="2"/><path d="M9 3h6v4H9zM9 12h6M9 16h6"/>',results:'<path d="M4 20V11h4v9M10 20V4h4v16M16 20v-7h4v7"/>',classes:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a5 5 0 0 1 10 0v2M16 7a3 3 0 0 1 0 6M16 15a5 5 0 0 1 5 5"/>',profile:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',signout:'<path d="M10 7V4H4v16h6v-3M13 7l5 5-5 5M7 12h11"/>',students:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',bank:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 8h6M9 12h6M9 16h4"/>',users:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',audit:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'};$('navigation').innerHTML=nav.map(([p,i,n])=>`<button class="nav-button" data-page="${p}"><span class="nav-icon" aria-hidden="true"><svg viewBox="0 0 24 24" width="23" height="23" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${navPaths[p]||navPaths.overview}</svg></span><span>${n}</span></button>`).join('');}
// Browser-only exam deterrents. Chrome/Windows screenshots and recordings cannot be prevented.
let examFocusEvents=0,examViolationPending=false,examExitInProgress=false;
function examProtectionActive(){return user?.role==='student'&&attempt?.status==='in_progress'&&!!document.getElementById('exam-protection-banner');}
function setExamProtection(enabled){
 document.body.classList.toggle('exam-protection-active',Boolean(enabled));
 if(!enabled){document.getElementById('exam-protection-watermark')?.remove();return;}
 let mark=document.getElementById('exam-protection-watermark');
 if(!mark){mark=document.createElement('div');mark.id='exam-protection-watermark';mark.setAttribute('aria-hidden','true');document.body.appendChild(mark);}
 // Identity deterrent is visible only while the student is viewing an active attempt.
 mark.textContent=(user?.full_name||'Student')+' · Attempt #'+attempt.id;
}
// Switching tabs or losing window focus ends this attempt. The browser cannot
// directly detect a screenshot; OS screenshot tools may incidentally cause blur.
async function endExamForFocusLoss(reason){
 if(!examProtectionActive()||examViolationPending||examExitInProgress)return;
 examViolationPending=true;
 clearInterval(timer);clearInterval(saveTimer);timer=null;saveTimer=null;
 const current=attempt.id;
 const banner=document.getElementById('exam-protection-banner');
 if(banner)banner.textContent='Examination ended: the exam tab/window lost focus. Saving and submitting your answers…';
 document.querySelectorAll('[data-question], [data-action="submit-attempt"]').forEach(el=>el.disabled=true);
 try{
  // Do not wait for periodic autosave; send the latest on-screen answers.
  const result=await api(`/attempts/${current}/focus-violation`,'POST',{answers:{...answerMap},reason});
  if(attempt?.id!==current)return;
  openAttempt(result.attempt,'Examination automatically submitted');
  toast('Your examination was submitted because you left the examination window.',true);
 }catch(err){
  if(attempt?.id!==current)return;
  if(banner){
   banner.textContent='Unable to confirm automatic submission. Check your connection, then click Retry automatic submission. Do not continue answering.';
   const retry=document.createElement('button');
   retry.className='primary';retry.type='button';retry.textContent='Retry automatic submission';
   retry.addEventListener('click',()=>endExamForFocusLoss(reason));
   banner.append(' ',retry);
  }
  toast(err.message||'Could not submit attempt.',true);
 }finally{examViolationPending=false;}
}
document.addEventListener('visibilitychange',()=>{if(document.hidden)void endExamForFocusLoss('tab_hidden');});
window.addEventListener('blur',()=>{if(!document.hidden)void endExamForFocusLoss('window_blur');});
document.addEventListener('contextmenu',e=>{if(examProtectionActive()&&e.target.closest('#content'))e.preventDefault();},true);
document.addEventListener('copy',e=>{if(examProtectionActive()&&e.target.closest('#content'))e.preventDefault();},true);
document.addEventListener('cut',e=>{if(examProtectionActive()&&e.target.closest('#content'))e.preventDefault();},true);
document.addEventListener('keydown',e=>{
 if(!examProtectionActive())return;
 // These browser shortcuts are deterrents only; OS screenshot shortcuts remain available.
 const k=e.key.toLowerCase();
 if((e.ctrlKey||e.metaKey)&&['p','s','u'].includes(k)){e.preventDefault();toast('Printing, saving, and viewing page source are restricted during an examination.',true);}
},true);
function stopExam(){clearInterval(timer);clearInterval(saveTimer);timer=null;saveTimer=null;setExamProtection(false);attempt=null;examViolationPending=false;examExitInProgress=false;}
async function navigate(next){if(busy||examViolationPending)return;if(attempt?.status==='in_progress'){examExitInProgress=true;let leave=false;try{leave=confirm('Leave the examination? Your timer will continue. Saved answers can be resumed. Switching tabs or windows will automatically submit the attempt.');}finally{examExitInProgress=false;}if(!leave)return;try{await queueSave();}catch(e){toast('Could not save answers. Stay on this page and retry.',true);return;}}stopExam();page=next;bankActive=false;bankRequest++;$('modal').close();$('breadcrumb').textContent=page==='overview'?(user.role==='student'?'Student Workspace':user.role==='instructor'?'Instructor Workspace':'Admin Workspace'):({exams:'Available Exams',results:'Results',users:'Users',audit:'Activity',profile:'Profile',students:'Students',classes:'My Classes',bank:'Question Bank'}[page]||page);document.querySelectorAll('.nav-button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('content').innerHTML='<div class="loading">Loading your workspace…</div>';try{if(page==='overview'||page==='exams'){exams=(await api('/exams')).exams;if(page==='overview'){results=(await api('/results')).results;renderOverview();}else renderExams();}else if(page==='results'){results=(await api('/results')).results;renderResults();}else if(page==='users'){users=(await api('/users')).users;renderUsers();}else if(page==='audit'){const{events}=await api('/audit');$('content').innerHTML=heading('Activity log','Recent examination and account activity.')+`<section class="card table-wrap"><table><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Details</th></tr></thead><tbody>${events.map(e=>`<tr><td>${esc(date(e.created_at))}</td><td>${esc(e.full_name||'Unavailable')}</td><td>${esc(e.action)}</td><td>${esc(e.details)}</td></tr>`).join('')}</tbody></table></section>`;}else if(page==='bank'){await openBank(false);}else if(page==='students'){await loadStudents();}else if(page==='classes'){classList=(await api('/classes')).classes;renderClasses();}else renderProfile();}catch(e){if(!user)return;if(e.status===401){showAuth();$('auth-error').textContent=e.message;}else $('content').innerHTML=empty(e.message);}}
function renderOverview(){
 const done=results.filter(r=>r.status!=='in_progress');
 const avg=done.length?Math.round(done.reduce((sum,r)=>sum+(r.total_points>0?r.score/r.total_points*100:0),0)/done.length):0;
 const student=user.role==='student';
 const greeting=`Hello, ${user.full_name.split(' ')[0]}!`;
 const heroTitle=student?'A little focus goes a long way.':'Great assessments start with good questions.';
 const heroCopy=student?'Choose an available examination, review the instructions, and give it your best. Your progress is saved as you work.':'Design an examination, add your questions, and publish when you are ready. Track participation and performance from your reports.';
 $('content').innerHTML=`<div class="overview-campus"><div class="campus-heading">${heading(greeting,'Your assessments, progress, and next steps in one place.')}</div><section class="hero"><span class="hero-mark" aria-hidden="true">🎓</span><div class="hero-copy"><span class="eyebrow">${student?'READY FOR YOUR NEXT CHALLENGE?':'MAKE EVERY ASSESSMENT COUNT'}</span><h2>${heroTitle}</h2><p>${heroCopy}</p></div><img class="hero-illustration" src="exam-clipboard.svg" alt="" aria-hidden="true"></section></div><section class="stats">${stat(student?'Available exams':'Total examinations',exams.length,'In your workspace','exams')}${stat(student?'Completed attempts':'Published exams',student?done.length:exams.filter(e=>e.status==='published').length,student?'Submitted or expired':'Open to students','completed')}${stat(student?'Average score':'Student attempts',student?avg+'%':results.length,'Across your assessments','score')}${stat('In progress',results.filter(r=>r.status==='in_progress').length,'Active examination attempts','clock')}</section><section class="overview-exams"><div class="card-head"><h2>${student?'Explore assessments':'Recent examinations'}</h2><button class="secondary" data-action="all-exams">View all <span aria-hidden="true">→</span></button></div><div class="exam-grid">${exams.slice(0,3).map(overviewExamCard).join('')}</div>${!exams.length?empty('Your examinations will appear here.'):''}</section>`;
}

function examCard(e){const student=user.role==='student';const now=Date.now();const available=(!e.opens_at||new Date(e.opens_at)<=now)&&(!e.closes_at||new Date(e.closes_at)>now);return `<article class="exam-card"><div>${badge(e.status)} <span class="muted fine">#${e.id}</span></div><h3>${esc(e.title)}</h3><p class="description">${esc(e.description||'No additional instructions.')}</p><div class="exam-meta"><span>◷ ${e.duration_minutes} min</span><span>▤ ${e.sample_count||e.question_count} questions</span><span>◎ ${e.passing_score}% to pass</span></div><small class="muted">${e.sample_count?`${e.sample_count} random questions from a pool of ${e.question_count}`:e.shuffle_questions?'Question order randomized':'Fixed question order'}</small><small class="muted">${e.class_only?'Assigned classes only':'Subject class membership required'}</small><small class="muted">${student?esc(e.instructor_name):`${e.total_points} ${e.sample_count?'pool':'total'} points`}</small><small class="muted">${e.opens_at?'Opens '+esc(date(e.opens_at)):'No opening restriction'}${e.closes_at?'<br>Closes '+esc(date(e.closes_at)):''}</small>${student?`<small class="muted">${e.used_attempts} / ${e.max_attempts} attempts used</small><div class="actions"><button class="primary" data-action="start" data-id="${e.id}" ${!e.active_attempt_id&&(!available||e.used_attempts>=e.max_attempts)?'disabled':''}>${e.active_attempt_id?'Resume examination →':!available?'Outside scheduled time':e.used_attempts>=e.max_attempts?'Attempt limit reached':'Start examination →'}</button></div>`:`<div class="actions"><button class="primary" data-action="questions" data-id="${e.id}">${e.locked?'View questions':'Manage questions'}</button>${!e.locked?`<button class="secondary" data-action="edit-exam" data-id="${e.id}">Edit</button><button class="secondary" data-action="audience" data-id="${e.id}">Assign classes</button><button class="danger" data-action="delete-exam" data-id="${e.id}">Delete</button>`:''}<button class="secondary" data-action="participation" data-id="${e.id}">Student participation</button><button class="secondary" data-action="duplicate" data-id="${e.id}">Duplicate</button><button class="secondary" data-action="status" data-id="${e.id}" data-status="${e.status==='published'?'closed':'published'}">${e.status==='published'?'Close exam':e.status==='closed'?'Reopen':'Publish'}</button></div>`}</article>`;}
function renderExams(){ $('content').innerHTML=heading(user.role==='student'?'Available examinations':'Your examinations',user.role==='student'?'Read the instructions and check the schedule before starting.':'Build, organize, and publish assessments for your students.',user.role==='student'?'':'<button class="primary" data-action="new-exam">+ Create examination</button>')+`<div class="toolbar"><input id="exam-search" type="search" placeholder="Search examinations…" aria-label="Search examinations">${user.role!=='student'?'<select id="exam-filter" aria-label="Filter by status"><option value="">All statuses</option><option>draft</option><option>published</option><option>closed</option></select>':''}</div><div id="exam-cards" class="exam-grid"></div>`;filterExams();}
function filterExams(){const term=($('exam-search')?.value||'').toLowerCase(),status=$('exam-filter')?.value||'';const rows=exams.filter(e=>(e.title+' '+e.description).toLowerCase().includes(term)&&(!status||e.status===status));$('exam-cards').innerHTML=rows.length?rows.map(examCard).join(''):empty('No examinations match your search.');}
function modal(title,html){$('modal-title').textContent=title;$('modal-body').innerHTML=html;$('modal').showModal();}
function localDate(v){if(!v)return '';const d=new Date(v);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function examForm(e={}){modal(e.id?'Edit examination':'Create examination',`<form id="exam-form" data-id="${e.id||''}"><label>Examination title<input name="title" required maxlength="150" value="${esc(e.title||'')}" placeholder="e.g. Web Development Midterm"></label><label>Instructions<textarea name="description" maxlength="3000">${esc(e.description||'')}</textarea></label><div class="form-grid"><label>Duration (minutes)<input name="duration_minutes" type="number" min="1" max="180" required value="${e.duration_minutes||30}"></label><label>Passing score (%)<input name="passing_score" type="number" min="0" max="100" required value="${e.passing_score??75}"></label><label>Allowed attempts<input name="max_attempts" type="number" min="1" max="5" required value="${e.max_attempts||1}"></label><label>Opens at (optional)<input name="opens_at" type="datetime-local" value="${localDate(e.opens_at)}"></label><label>Closes at (optional)<input name="closes_at" type="datetime-local" value="${localDate(e.closes_at)}"></label></div><fieldset><legend>Randomized exams</legend><label class="roster-check"><input type="checkbox" name="shuffle_questions" ${e.shuffle_questions??!e.id?'checked':''}>Shuffle question order for each attempt</label><label class="roster-check"><input type="checkbox" name="shuffle_options" ${e.shuffle_options??!e.id?'checked':''}>Shuffle multiple-choice answers</label><label>Random questions per attempt (0 = use all)<input name="sample_count" type="number" min="0" max="100" required value="${e.sample_count||0}"></label><p class="fine muted">Questions and answer keys are saved once per attempt. Refreshing or resuming keeps the same order. A random subset requires enough questions in the exam pool.</p></fieldset><p class="note">Times use your computer’s local timezone. Publishing freezes questions and settings. Use Duplicate to create an editable copy later.</p><button class="primary wide">${e.id?'Save changes':'Create draft'}</button><p class="error" id="form-error" role="alert"></p></form>`);}
async function openQuestions(n){const d=await api(`/exams/${n}/questions`);questionExam=d.exam;questions=d.questions;$('breadcrumb').textContent='Workspace / Question editor';$('content').innerHTML=heading(questionExam.title,`${questions.length} questions · ${questions.reduce((s,q)=>s+q.points,0)} total points`,`${!questionExam.locked?'<button class="primary" data-action="new-question">+ Add question</button><button class="secondary" data-action="bank-pick">Add from bank</button><button class="secondary" data-action="ai-generate">✦ Generate with AI</button>':''}<button class="secondary" data-action="all-exams">← Examinations</button>`)+(questionExam.locked?'<p class="note">This published examination is frozen. Duplicate it to edit its content.</p>':'<p class="note">Add multiple choice, true / false, identification, or enumeration questions. An exam can contain any mix.</p>')+questions.map((q,i)=>`<article class="question"><div class="card-head"><span class="eyebrow">QUESTION ${i+1} · ${q.points} POINT(S)</span><button class="secondary" data-action="bank-copy" data-id="${q.id}">Save to bank</button>${!questionExam.locked?`<div><button class="secondary" data-action="edit-question" data-id="${q.id}">Edit</button> <button class="danger" data-action="delete-question" data-id="${q.id}">Delete</button></div>`:''}</div><h3>${esc(q.prompt)}</h3>${instructorKey(q)}</article>`).join('')+(!questions.length?empty('No questions yet. Add your first question to get started.'):'');}
function questionForm(q={},bank=false){const type=qType(q);modal(bank?(q.id?'Edit bank question':'Create bank question'):(q.id?'Edit question':'Add question'),`<form id="${bank?'bank-form':'question-form'}" data-id="${q.id||''}"><label>Question<textarea name="prompt" required maxlength="2000">${esc(q.prompt||'')}</textarea></label>${bank?bankMetaFields(q):''}<div class="form-grid"><label>Question type<select id="question-type">${typeOptions(type)}</select></label><label>Points<input name="points" type="number" min="1" max="100" value="${q.points||1}" required></label></div><div id="options-form"></div><button class="primary wide">Save question</button><p class="error" id="form-error" role="alert"></p></form>`);renderQuestionFields(type,q);}
function renderOptionForm(count,options,index=0){$('options-form').innerHTML=Array.from({length:count},(_,i)=>`<label>Option ${String.fromCharCode(65+i)}<input name="option${i}" required maxlength="500" value="${esc(options?.[i]||(count===2?(i===0?'True':'False'):''))}"></label>`).join('')+`<label>Correct answer<select name="correct_index">${Array.from({length:count},(_,i)=>`<option value="${i}" ${i===index?'selected':''}>Option ${String.fromCharCode(65+i)}</option>`).join('')}</select></label>`;}
function renderResults(){const done=results.filter(r=>r.score!==null);$('content').innerHTML=heading(user.role==='student'?'Your results':'Results & reports','Review examination attempts, scores, and completion status.',`<button class="secondary" data-action="print">Print</button> <button class="primary" data-action="export">Export CSV ↓</button>`)+`<section class="stats">${stat('Total attempts',results.length,'All examinations')}${stat('Completed',done.length,'Submitted or expired')}${stat('Passed',done.filter(r=>r.score/r.total_points*100>=r.passing_score).length,'Met the passing threshold')}${stat('Average score',done.length?Math.round(done.reduce((s,r)=>s+r.score/r.total_points*100,0)/done.length)+'%':'—','Completed attempts')}</section><div class="toolbar"><input id="result-search" type="search" aria-label="Search results" placeholder="Search by exam, student, or email…"><select id="result-filter" aria-label="Filter results"><option value="">All statuses</option><option value="submitted">Submitted</option><option value="expired">Expired</option><option value="in_progress">In progress</option></select></div><section class="card"><div class="table-wrap"><table><thead><tr><th>Examination</th>${user.role!=='student'?'<th>Student</th>':''}<th>Status</th><th>Score</th><th>Outcome</th><th>Completed</th><th></th></tr></thead><tbody id="result-rows"></tbody></table></div><div id="no-results" hidden>${empty('No results yet.')}</div></section>`;filterResults();}
function filteredResults(){const term=($('result-search')?.value||'').toLowerCase(),status=$('result-filter')?.value||'';return results.filter(r=>(r.title+' '+r.full_name+' '+r.email).toLowerCase().includes(term)&&(!status||r.status===status));}
function filterResults(){const rows=filteredResults();$('no-results').hidden=!!rows.length;$('result-rows').innerHTML=rows.map(r=>`<tr><td><strong>${esc(r.title)}</strong><small>Attempt ${r.attempt_number}</small></td>${user.role!=='student'?`<td>${esc(r.full_name)}<small>${esc(r.email)}</small></td>`:''}<td>${badge(r.status)}</td><td class="score">${r.score===null?'—':`${r.score}/${r.total_points} · ${percent(r)}%`}</td><td>${r.score===null?'—':r.score/r.total_points*100>=r.passing_score?'Passed':'Below threshold'}</td><td>${esc(date(r.submitted_at))}</td><td><button class="secondary" data-action="review" data-id="${r.id}">${r.status==='in_progress'&&user.role==='student'?'Resume':'Details'}</button></td></tr>`).join('');}
function exportCSV(){const safe=v=>{let s=String(v??'');if(/^\s*[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const rows=[['Examination','Student','Email','Attempt','Status','Score','Total','Percentage','Passing threshold','Completed'],...filteredResults().map(r=>[r.title,r.full_name,r.email,r.attempt_number,r.status,r.score,r.total_points,percent(r),r.passing_score,r.submitted_at||''])];const blob=new Blob(['\ufeff'+rows.map(r=>r.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='ExamPortal-results.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
async function startExam(n){const e=exams.find(e=>e.id===n);if(!e)return;if(!e.active_attempt_id&&!confirm(`Start ${e.title}?\n\n${e.duration_minutes} minutes · ${e.sample_count||e.question_count} questions\nIMPORTANT: Switching tabs or leaving this window automatically submits your attempt, even if unanswered. The browser cannot reliably detect screenshots.\n\n${e.description}`))return;const d=await api(`/exams/${n}/start`,'POST');openAttempt(d.attempt,e.title);}
async function review(n){const d=await api(`/attempts/${n}`);const r=results.find(r=>r.id===n);if(d.attempt.status==='in_progress'&&user.role!=='student'){toast('This student is still taking the examination.');return;}openAttempt(d.attempt,r?.title||'Examination');}
function openAttempt(a,title){stopExam();attempt=a;answerMap={...a.answers};clockOffset=new Date(a.server_time).getTime()-Date.now();if(a.status!=='in_progress'){renderReview(a,title);return;}examFocusEvents=0;examViolationPending=false;$('breadcrumb').textContent='Workspace / Examination';$('content').innerHTML=heading(title,'Answer each question according to its type. Answers save automatically.')+`<div id="exam-protection-banner" class="exam-protection-banner" role="status">Exam integrity mode is active. Copying and right-click are restricted within the examination. Screen capture cannot be blocked in Chrome. Switching tabs, minimizing, or leaving the examination window automatically submits this attempt. Some system dialogs may also trigger this rule. Screenshots cannot be detected reliably in Chrome.</div><div class="exam-bar"><div><strong id="answered-count"></strong><small id="save-status" class="muted"> · Answers loaded</small></div><div><span class="fine muted">TIME LEFT </span><span id="timer" class="timer"></span></div></div><div class="exam-layout"><section>${a.questions.map((q,i)=>`<article class="question" id="q-${q.id}"><span class="eyebrow">QUESTION ${i+1} · ${esc(typeLabels[qType(q)])} · ${q.points} POINT(S)</span><h3>${esc(q.prompt)}</h3>${studentFields(q)}</article>`).join('')}</section><aside class="card question-nav"><h3>Your progress</h3><div class="number-grid">${a.questions.map((q,i)=>`<button data-action="jump" data-id="${q.id}" id="jump-${q.id}">${i+1}</button>`).join('')}</div><p class="fine muted">Green numbers are answered. You can review your choices before submitting.</p><button class="primary wide" data-action="submit-attempt">Submit examination →</button></aside></div>`;setExamProtection(true);updateProgress();tick();timer=setInterval(tick,1000);saveTimer=setInterval(()=>{queueSave().catch(e=>saveError(e));},10000);}
function updateProgress(){if(!$('answered-count'))return;$('answered-count').textContent=`${answerCount()} / ${attempt.questions.length} answered`;attempt.questions.forEach(q=>$('jump-'+q.id)?.classList.toggle('answered',hasAnswer(answerMap[q.id])));}
function tick(){if(!attempt||!$('timer'))return;const seconds=Math.max(0,Math.ceil((new Date(attempt.deadline_at)-Date.now()-clockOffset)/1000));$('timer').textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;$('timer').classList.toggle('low',seconds<120);if(seconds===0&&!busy){clearInterval(timer);clearInterval(saveTimer);finishAttempt(true);}}
function saveError(e){if($('save-status'))$('save-status').textContent=' · Save failed — retrying';toast(e.message+' Your unsaved choices are still on this page.',true);}
function queueSave(){if(!attempt||attempt.status!=='in_progress')return saving;const n=attempt.id,answers={...answerMap};saving=saving.catch(()=>{}).then(async()=>{if(!attempt||attempt.id!==n)return;const d=await api(`/attempts/${n}/answers`,'PUT',{answers});if(d.attempt.status!=='in_progress'){openAttempt(d.attempt,'Examination completed');return;}if($('save-status'))$('save-status').textContent=' · Saved '+new Date().toLocaleTimeString();});return saving;}
async function finishAttempt(expired=false){if(busy||!attempt||examViolationPending)return;if(!expired){examExitInProgress=true;let agreed=false;try{agreed=confirm(`Submit examination? ${answerCount()} of ${attempt.questions.length} questions answered. You cannot change your answers after submitting.`);}finally{examExitInProgress=false;}if(!agreed)return;}busy=true;document.querySelectorAll('[data-question], [data-action="submit-attempt"]').forEach(x=>x.disabled=true);try{await saving.catch(()=>{});const d=await api(`/attempts/${attempt.id}/submit`,'POST',{answers:{...answerMap}});openAttempt(d.attempt,'Examination completed');toast(d.message);}catch(e){saveError(e);document.querySelectorAll('[data-question], [data-action="submit-attempt"]').forEach(x=>x.disabled=false);if(expired)timer=setInterval(tick,5000);}finally{busy=false;}}
function renderReview(a,title){const passed=a.score/a.total_points*100>=a.passing_score;$('content').innerHTML=heading(title,'Your completed examination and answer review.',`<button class="secondary" data-action="all-results">← Results</button>`)+`<section class="card result-banner"><span class="eyebrow">${passed?'WELL DONE':'KEEP LEARNING'}</span><div class="big-score">${Math.round(a.score/a.total_points*100)}%</div><p><strong>${a.score} / ${a.total_points} points</strong> · ${passed?'Passed':'Below passing threshold'}</p><p class="muted">${badge(a.status)} · Attempt ${a.attempt_number} · Passing score ${a.passing_score}%</p><small class="muted">Completed ${esc(date(a.submitted_at))}</small></section>`+a.questions.map((q,i)=>`<article class="question"><span class="eyebrow">QUESTION ${i+1} · ${q.earned_points??(a.answers[q.id]===q.correct_index?q.points:0)}/${q.points} POINT(S)</span><h3>${esc(q.prompt)}</h3>${isText(q)?`<p><strong>Your answer:</strong> ${esc(Array.isArray(a.answers[q.id])?a.answers[q.id].filter(Boolean).join(', '):a.answers[q.id]||'Unanswered')}</p><p><strong>Accepted answers:</strong></p>${instructorKey(q)}`:q.options.map((o,j)=>`<div class="option ${j===q.correct_index?'correct':a.answers[q.id]===j?'wrong':''}"><b>${String.fromCharCode(65+j)}.</b><span>${esc(o)} ${j===q.correct_index?'✓ Correct answer':''}${a.answers[q.id]===j?' · Your answer':''}</span></div>`).join('')}${a.answers[q.id]===undefined?'<p class="muted fine">You did not answer this question.</p>':''}</article>`).join('');}
function renderUsers(){ $('content').innerHTML=heading('People & permissions','Create accounts and manage access to the examination system.','<button class="primary" data-action="new-user">+ Add user</button>')+`<div class="toolbar"><input id="user-search" type="search" aria-label="Search users" placeholder="Search by name, email, or role…"></div><section class="card table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th></th></tr></thead><tbody id="user-rows"></tbody></table></section>`;filterUsers();}
function filterUsers(){const s=($('user-search').value||'').toLowerCase();$('user-rows').innerHTML=users.filter(u=>(u.full_name+u.email+u.role).toLowerCase().includes(s)).map(u=>`<tr><td>${esc(u.full_name)}</td><td>${esc(u.email)}</td><td>${badge(u.role)}</td><td>${u.active?'Active':'Deactivated'}</td><td>${u.id===user.id?'Your account':`<button class="secondary" data-action="edit-user" data-id="${u.id}">Manage</button>`}</td></tr>`).join('');}
function userForm(u={}){modal(u.id?'Manage user':'Create user',`<form id="user-form" data-id="${u.id||''}"><label>Full name<input name="full_name" required minlength="2" maxlength="100" value="${esc(u.full_name||'')}"></label>${u.id?`<p class="muted">${esc(u.email)}</p>`:'<label>Email<input name="email" type="email" required maxlength="254"></label><label>Initial password<input name="password" type="password" required minlength="8" autocomplete="new-password"></label>'}<label>Role<select name="role">${['student','instructor','admin'].map(r=>`<option ${u.role===r?'selected':''}>${r}</option>`).join('')}</select></label>${u.id?`<label>Account status<select name="active"><option value="true" ${u.active?'selected':''}>Active</option><option value="false" ${!u.active?'selected':''}>Deactivated</option></select></label><p class="note">Deactivate accounts to remove access while preserving examination history.</p>`:''}<button class="primary wide">Save user</button><p class="error" id="form-error" role="alert"></p></form>`);}
function renderProfile(){ $('content').innerHTML=heading('Your profile','Keep your name and password up to date.')+`<section class="card"><form id="profile-form"><div class="form-grid"><label>Full name<input name="full_name" required minlength="2" maxlength="100" value="${esc(user.full_name)}"></label><label>Email<input value="${esc(user.email)}" disabled></label><label>Current password<input name="current_password" type="password" autocomplete="current-password"></label><label>New password<input name="new_password" type="password" minlength="8" autocomplete="new-password"></label></div><p class="note">Leave password fields empty to update only your name.</p><button class="primary">Save profile</button><p class="error" id="form-error" role="alert"></p></form></section>`;}
fetch('/api/google-config').then(r=>r.json()).then(config=>{$('google-login-wrap').dataset.enabled=String(Boolean(config.enabled));$('google-login-wrap').hidden=!config.enabled;}).catch(()=>{});
const googleError=new URLSearchParams(location.search).get('google_error');
