$('auth-switch').addEventListener('click',()=>{registering=!registering;$('auth-form').reset();$('forgot-password').hidden=registering;$('google-login-wrap').hidden=registering||document.querySelector('#google-login-wrap').dataset.enabled!=='true';updateRegistrationFields();$('name-field').hidden=!registering;$('confirm-field').hidden=!registering;$('full-name').required=registering;$('confirm-password').required=registering;$('password').minLength=registering?8:1;$('password').autocomplete=registering?'new-password':'current-password';$('auth-title').textContent=registering?'Create your account':'Welcome back';$('auth-description').textContent=registering?'Choose Student or Instructor to create your account.':'Sign in to continue your learning journey.';$('auth-submit').textContent=registering?'Create account →':'Sign in →';$('auth-switch').textContent=registering?'Already registered? Sign in':'New here? Create an account';$('auth-error').textContent='';});
$('auth-form').addEventListener('submit',async e=>{e.preventDefault();if(registering&&$('password').value!==$('confirm-password').value){$('auth-error').textContent='Passwords do not match.';return;}$('auth-submit').disabled=true;$('auth-switch').disabled=true;try{const body=Object.fromEntries(new FormData(e.target));const d=await api(registering?'/register':'/login','POST',body);if(registering){$('auth-switch').disabled=false;$('auth-switch').click();$('email').value=body.email;toast(d.message);}else{user=d.user;e.target.reset();setupShell();await navigate('overview');}}catch(e){$('auth-error').textContent=e.message;}finally{$('auth-submit').disabled=false;$('auth-switch').disabled=false;}});
async function logout(){
 if(busy||!user)return;
 const active=attempt?.status==='in_progress';
 if(active&&!confirm('Sign out? Your answers will be saved and the examination timer will continue.'))return;
 busy=true;
 const buttons=[$('logout'),...document.querySelectorAll('[data-page="signout"]')];
 const labels=buttons.map(b=>b.innerHTML);
 buttons.forEach(b=>{b.disabled=true;b.setAttribute('aria-busy','true');b.textContent='Signing out…';});
 $('shell').inert=true;$('logout-loading').hidden=false;
 if(active){clearInterval(saveTimer);saveTimer=null;}
 try{
  if(active)await queueSave();
  await Promise.all([api('/logout','POST'),new Promise(resolve=>setTimeout(resolve,450))]);authEpoch++;
  clearTimeout(studentSearchTimer);clearTimeout(lookupTimer);clearTimeout(bankSearchTimer);
  studentRequest++;lookupRequest++;bankRequest++;bankActive=false;
  exams=[];results=[];users=[];questions=[];answerMap={};classList=[];registeredStudents=[];rosterStudents=[];bankRows=[];
  questionExam=null;roster=null;participation=null;bankSelection.clear();saving=Promise.resolve();page='overview';csrf='';
  $('modal').close();$('modal-body').replaceChildren();$('content').replaceChildren();
  showAuth();
  if(registering)$('auth-switch').click();
  $('auth-form').reset();if(!googleError)$('auth-error').textContent='';$('email').focus();
  toast('Signed out successfully.');
 }catch(e){
  if(active&&attempt?.status==='in_progress')saveTimer=setInterval(()=>queueSave().catch(saveError),10000);
  toast('Could not sign out. '+e.message+' Please try again.',true);
 }finally{
  busy=false;$('shell').inert=false;$('logout-loading').hidden=true;
  buttons.forEach((b,i)=>{b.disabled=false;b.removeAttribute('aria-busy');b.innerHTML=labels[i];});
 }
}
$('logout').addEventListener('click',()=>logout().catch(e=>toast(e.message,true)));
$('navigation').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b){if(b.dataset.page==='signout')logout().catch(e=>toast(e.message,true));else navigate(b.dataset.page);}});
$('modal-close').addEventListener('click',()=>{if(!busy)$('modal').close();});
$('modal').addEventListener('cancel',e=>{if(busy)e.preventDefault();});
document.addEventListener('input',e=>{if(e.target.dataset.question&&e.target.type!=='radio')readStudentAnswer(e.target);if(e.target.id==='exam-search')filterExams();if(e.target.id==='result-search')filterResults();if(e.target.id==='user-search')filterUsers();});
document.addEventListener('change',e=>{if(e.target.id==='exam-filter')filterExams();if(e.target.id==='result-filter')filterResults();if(e.target.id==='question-type')renderQuestionFields(e.target.value);if(e.target.dataset.question){readStudentAnswer(e.target);queueSave().catch(saveError);}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled||busy)return;const n=Number(b.dataset.id),action=b.dataset.action;try{if(action==='ai-generate')aiForm();else if(action==='new-exam')examForm();else if(action==='edit-exam')examForm(exams.find(x=>x.id===n));else if(action==='all-exams')await navigate('exams');else if(action==='all-results')await navigate('results');else if(action==='questions')await openQuestions(n);else if(action==='new-question')questionForm();else if(action==='edit-question')questionForm(questions.find(q=>q.id===n));else if(action==='new-user')userForm();else if(action==='edit-user')userForm(users.find(u=>u.id===n));else if(action==='start')await startExam(n);else if(action==='review')await review(n);else if(action==='submit-attempt')await finishAttempt();else if(action==='jump')$('q-'+n)?.scrollIntoView({behavior:'smooth',block:'center'});else if(action==='export')exportCSV();else if(action==='print')window.print();else{let endpoint,method='POST';if(action==='delete-exam'){if(!confirm('Delete this draft and its questions?'))return;endpoint=`/exams/${n}`;method='DELETE';}else if(action==='duplicate')endpoint=`/exams/${n}/duplicate`;else if(action==='status'){if(!confirm(b.dataset.status==='published'?'Publish this exam? Questions and settings will be frozen.':'Close this exam to new attempts? Access to active attempts is blocked until the student rejoins with a valid code.'))return;endpoint=`/exams/${n}/status`;}else if(action==='delete-question'){if(!confirm('Delete this question?'))return;endpoint=`/exams/${questionExam.id}/questions/${n}`;method='DELETE';}if(endpoint){busy=true;b.disabled=true;try{const d=await api(endpoint,method,action==='status'?{status:b.dataset.status}:{});toast(d.message);if(action==='delete-question')await openQuestions(questionExam.id);else{busy=false;await navigate('exams');}}finally{busy=false;b.disabled=false;}}}}catch(e){toast(e.message,true);}});
document.addEventListener('submit',async e=>{if(!['exam-form','question-form','user-form','profile-form'].includes(e.target.id))return;e.preventDefault();if(busy)return;const f=e.target,b=Object.fromEntries(new FormData(f)),n=f.dataset.id;busy=true;const button=f.querySelector('button');button.disabled=true;try{let d;if(f.id==='exam-form'){for(const k of ['duration_minutes','passing_score','max_attempts','sample_count'])b[k]=Number(b[k]);b.shuffle_questions=b.shuffle_questions==='on';b.shuffle_options=b.shuffle_options==='on';for(const k of ['opens_at','closes_at'])b[k]=b[k]?new Date(b[k]).toISOString():null;d=await api('/exams'+(n?'/'+n:''),n?'PUT':'POST',b);$('modal').close();busy=false;await navigate('exams');}else if(f.id==='question-form'){const type=$('question-type').value,count=type==='true_false'?2:4;d=await api(`/exams/${questionExam.id}/questions`+(n?'/'+n:''),n?'PUT':'POST',{prompt:b.prompt,question_type:type,options:['identification','enumeration'].includes(type)?[]:Array.from({length:count},(_,i)=>b['option'+i]),accepted_answers:['identification','enumeration'].includes(type)?parseKey(b.key):[],correct_index:Number(b.correct_index),points:Number(b.points)});$('modal').close();await openQuestions(questionExam.id);}else if(f.id==='user-form'){if(n)b.active=b.active==='true';d=await api('/users'+(n?'/'+n:''),n?'PUT':'POST',b);$('modal').close();busy=false;await navigate('users');}else{d=await api('/profile','PUT',b);user=(await api('/me')).user;setupShell();renderProfile();}toast(d.message);}catch(e){if($('form-error'))$('form-error').textContent=e.message;else toast(e.message,true);}finally{busy=false;button.disabled=false;}});
window.addEventListener('beforeunload',e=>{if(attempt?.status==='in_progress'){e.preventDefault();e.returnValue='';}});
(async()=>{try{csrf=(await api('/csrf')).token;try{user=(await api('/me')).user;}catch(e){if(e.status!==401)throw e;}if(user){setupShell();await navigate('overview');}else showAuth();}catch(e){showAuth();$('auth-error').textContent=e.message+' Check that the server is running.';}})();

let aiDrafts=[];
function aiForm(){modal('Generate questions with AI',`<form id="ai-form"><p class="note">Your topic and lesson text are sent to Google Gemini. Use learning materials you are allowed to share. Review the generated answer keys before saving. Up to 100 questions are generated in smaller batches of 10 for more reliable output. This requires several Gemini requests and available API quota. Enter topics or learning objectives below; do not paste a prewritten question bank, because Gemini may repeat or reproduce those questions. Mixed requires at least 4 questions and distributes them across all four types.</p><label>Topic<input name="topic" required minlength="2" maxlength="200" placeholder="e.g. HTML, CSS, and PostgreSQL"></label><label>Lesson or learning objectives (optional)<textarea name="lesson" maxlength="12000" placeholder="Paste lesson notes to guide the questions"></textarea></label><div class="form-grid"><label>Number of questions<input name="count" type="number" min="1" max="100" value="10" required></label><label>Difficulty<select name="difficulty"><option value="easy">Easy</option><option value="medium" selected>Medium</option><option value="hard">Hard</option></select></label><label>Question type<select name="question_type">${typeOptions("multiple_choice",true)}</select></label></div><button class="primary wide">Generate draft questions</button><p class="error" id="form-error" role="alert"></p></form>`);}
function aiReview(){modal('Review AI questions',`<form id="ai-review"><p class="note">Review questions and answer keys before saving. Uncheck unwanted questions. Text matching ignores case and extra spaces; enumeration needs all required items, in any order, for full points.</p>${aiDrafts.map((q,i)=>`<section class="question" data-ai-index="${i}"><label><input type="checkbox" name="include${i}" checked> Include question ${i+1} · ${esc(typeLabels[qType(q)])}</label><label>Question<textarea name="prompt${i}" required maxlength="2000">${esc(q.prompt)}</textarea></label>${isText(q)?keyFields(q,i):q.options.map((o,j)=>`<label>Option ${String.fromCharCode(65+j)}<input name="option${i}_${j}" required maxlength="500" value="${esc(o)}" ${qType(q)==='true_false'?'readonly':''}></label>`).join('')+`<label>Correct answer<select name="correct${i}">${q.options.map((o,j)=>`<option value="${j}" ${q.correct_index===j?'selected':''}>Option ${String.fromCharCode(65+j)}</option>`).join('')}</select></label>`}<label>Points<input name="points${i}" type="number" required min="1" max="100" value="${q.points}"></label></section>`).join('')}<button class="primary wide">Add selected questions to draft</button><p class="error" id="form-error" role="alert"></p></form>`);}
document.addEventListener('submit',async e=>{
 if(!['ai-form','ai-review'].includes(e.target.id))return;e.preventDefault();if(busy)return;const f=e.target,b=Object.fromEntries(new FormData(f)),button=f.querySelector('button'),examId=questionExam.id;busy=true;button.disabled=true;const old=button.textContent;button.textContent=f.id==='ai-form'?'Generating… please wait':'Saving reviewed questions…';
 try{if(f.id==='ai-form'){const d=await api(`/exams/${examId}/ai/generate`,'POST',{...b,count:Number(b.count),question_type:b.question_type});aiDrafts=d.questions;aiReview();}else{const selected=aiDrafts.flatMap((q,i)=>b['include'+i]?[{prompt:b['prompt'+i],question_type:qType(q),accepted_answers:isText(q)?parseKey(b['key'+i]):[],options:q.options.map((_,j)=>b[`option${i}_${j}`]),correct_index:Number(b['correct'+i]),points:Number(b['points'+i])}]:[]);if(!selected.length)throw Error('Select at least one question.');const d=await api(`/exams/${examId}/questions/bulk`,'POST',{questions:selected});aiDrafts=[];$('modal').close();await openQuestions(examId);toast(d.message);}}
 catch(e){if($('form-error'))$('form-error').textContent=e.message;else toast(e.message,true);}finally{busy=false;button.disabled=false;button.textContent=old;}
});

function renderQuestionFields(type,q={}){if(['identification','enumeration'].includes(type))$('options-form').innerHTML=keyFields({...q,question_type:type});else{renderOptionForm(type==='true_false'?2:4,q.options,q.correct_index);if(type==='true_false')document.querySelectorAll('#options-form input').forEach((el,i)=>{el.value=i===0?'True':'False';el.readOnly=true;});}}

let classList=[],registeredStudents=[],roster=null,rosterStudents=[],participation=null,studentSearchTimer,lookupTimer,studentRequest=0;
async function loadStudents(search=''){
 const request=++studentRequest;const d=await api('/students?search='+encodeURIComponent(search));if(request!==studentRequest||page!=='students')return;registeredStudents=d.students;
 if(!$('student-list-rows'))$('content').innerHTML=heading('Registered students','Students create their own accounts and join subject classes using the instructor’s class code.')+`<div class="toolbar"><input id="student-list-search" type="search" aria-label="Search registered students" placeholder="Search names or emails…"></div><p class="muted fine" id="student-list-count"></p><section class="card table-wrap"><table><thead><tr><th scope="col">No.</th><th>Student</th><th>Email</th><th>Status</th><th>Registered</th></tr></thead><tbody id="student-list-rows"></tbody></table></section>`;
 $('student-list-count').textContent=`${d.students.length} students shown (up to 500 per search).`;$('student-list-rows').innerHTML=d.students.map((s,index)=>`<tr><td class="student-row-number">${index+1}</td><td>${esc(s.full_name)}</td><td>${esc(s.email)}</td><td>${s.active?'Active':'Inactive'}</td><td>${esc(date(s.created_at))}</td></tr>`).join('')||'<tr><td colspan="5">No registered students match this search.</td></tr>';
}
function renderClasses(){const student=user.role==='student';$('content').innerHTML=heading(student?'Your classes':'Classes & sections',student?'Your enrolled classes. Assigned exams appear in Available Exams.':'Create a class for each subject and section. Share its join code with your students.',student?'<button class="primary" data-action="join-class">+ Join class</button>':'<button class="primary" data-action="new-class">+ Create class</button>')+`<div class="exam-grid">${classList.map(c=>`<article class="exam-card"><span class="eyebrow">${esc(c.instructor_name)}</span><h3>${esc(c.name)}</h3><p>${esc(c.description||'No additional description.')}</p>${!student?`<p class="muted">${c.student_count} enrolled students</p><p><strong>Class code:</strong> <code>${esc(c.join_code||'Not generated yet')}</code></p><div class="actions"><button class="secondary" data-action="rotate-class-code" data-id="${c.id}">${c.join_code?'Reset code':'Generate code'}</button><button class="primary" data-action="class-roster" data-id="${c.id}">Manage students</button><button class="secondary" data-action="edit-class" data-id="${c.id}">Edit</button><button class="danger" data-action="delete-class" data-id="${c.id}">Delete</button></div>`:''}</article>`).join('')}</div>`+(!classList.length?empty(student?'You are not enrolled in a class yet. Click Join class and enter the code from your instructor.':'No classes yet. Create a class to organize your students.'):'');}
function classForm(c={}){modal(c.id?'Edit class':'Create class',`<form id="class-form" data-id="${c.id||''}"><label>Class / section name<input name="name" required maxlength="100" value="${esc(c.name||'')}" placeholder="BSIT 4A — Web Development"></label><label>Description<textarea name="description" maxlength="1000">${esc(c.description||'')}</textarea></label><button class="primary wide">Save class</button><p class="error" id="form-error" role="alert"></p></form>`);}
async function openRoster(n){const d=await api(`/classes/${n}/students`);roster=d.class;rosterStudents=d.students;$('breadcrumb').textContent='Workspace / Class roster';$('content').innerHTML=heading(roster.name,`${d.students.length} enrolled students. Removing enrollment keeps student accounts, attempts, and results.`,`<button class="secondary" data-action="back-classes">← Classes</button>`)+`<section class="card table-wrap"><table><thead><tr><th>Student</th><th>Email</th><th>Status</th><th>Enrolled</th><th></th></tr></thead><tbody>${d.students.map(s=>`<tr><td>${esc(s.full_name)}</td><td>${esc(s.email)}</td><td>${s.active?'Active':'Inactive'}</td><td>${esc(date(s.enrolled_at))}${s.joined_via_code?'':' · Needs class code'}</td><td><button class="danger" data-action="remove-student" data-id="${s.id}">Remove</button></td></tr>`).join('')||'<tr><td colspan="5">No students enrolled. Share the class code so students can join.</td></tr>'}</tbody></table></section>`;}
async function enrollForm(){modal('Enroll a registered student',`<form id="enroll-form" data-id="${roster.id}"><p class="note">Students register themselves. Search their name or email, select their account, then enroll.</p><label>Search students<input id="enrollment-search" type="search" placeholder="Name or email"></label><label>Registered student<select name="student_id" id="enrollment-options" required><option value="">Loading…</option></select></label><button class="primary wide">Enroll student</button><p class="error" id="form-error" role="alert"></p></form>`);await enrollmentLookup('');}
let lookupRequest=0;
async function enrollmentLookup(search){const request=++lookupRequest;const d=await api('/students?search='+encodeURIComponent(search));if(request!==lookupRequest||!$('enrollment-options'))return;const available=d.students.filter(s=>s.active&&!rosterStudents.some(r=>r.id===s.id));$('enrollment-options').innerHTML='<option value="">'+(available.length?'Select a student':'No eligible students found')+'</option>'+available.map(s=>`<option value="${s.id}">${esc(s.full_name)} — ${esc(s.email)}</option>`).join('');}
async function audienceForm(n){const [a,c]=await Promise.all([api(`/exams/${n}/audience`),api('/classes')]);modal('Assign examination audience',`<form id="audience-form" data-id="${n}"><p class="note">Audience changes are allowed on draft exams. Publishing freezes these settings. Students must join a selected subject class using its code before accessing exams.</p><label>Class access (required)<select name="class_only"><option value="true" ${a.class_only?'selected':''}>Students who joined selected classes with a code</option></select></label><fieldset><legend>Classes / sections</legend>${c.classes.map(cl=>`<label class="roster-check"><input type="checkbox" name="class_ids" value="${cl.id}" ${a.class_ids.includes(cl.id)?'checked':''}>${esc(cl.name)} · ${cl.student_count} students</label>`).join('')||'<p>Create a class first in Classes & Sections.</p>'}</fieldset><button class="primary wide">Save audience</button><p class="error" id="form-error" role="alert"></p></form>`);}
async function openParticipation(n){const d=await api(`/exams/${n}/participation`);participation=d;$('breadcrumb').textContent='Workspace / Student participation';const done=d.students.filter(s=>s.completed>0),active=d.students.filter(s=>s.in_progress>0),pending=d.students.filter(s=>!s.attempts);$('content').innerHTML=heading(d.exam.title,'Participation of the current audience. Historical attempts remain in Results & Reports.',`<button class="secondary" data-action="export-participation">Export CSV</button><button class="secondary" data-action="all-exams">← Examinations</button>`)+`<section class="stats">${stat('Listed students',d.students.length,d.exam.class_only?'Assigned class rosters':'Subject class membership required')}${stat('Completed',done.length,'Submitted or expired')}${stat('In progress',active.length,'Active attempts')}${stat('Not started',pending.length,'No attempts yet')}</section><div class="toolbar"><input type="search" id="participation-search" placeholder="Search students…" aria-label="Search participation"><select id="participation-filter" aria-label="Filter participation"><option value="">All students</option><option value="completed">Completed</option><option value="in_progress">In progress</option><option value="not_started">Not started</option></select></div><section class="card table-wrap"><table><thead><tr><th>Student</th><th>Email</th><th>Account</th><th>Participation</th><th>Attempts</th><th>Best score</th></tr></thead><tbody id="participation-rows"></tbody></table></section>`;filterParticipation();}
function participationState(s){return s.in_progress?'in_progress':s.completed?'completed':'not_started';}
function filteredParticipation(){const term=($('participation-search')?.value||'').toLowerCase(),status=$('participation-filter')?.value||'';return participation.students.filter(s=>(s.full_name+' '+s.email).toLowerCase().includes(term)&&(!status||(status==='completed'?s.completed>0:participationState(s)===status)));}
function filterParticipation(){$('participation-rows').innerHTML=filteredParticipation().map(s=>`<tr><td>${esc(s.full_name)}</td><td>${esc(s.email)}</td><td>${s.active?'Active':'Inactive'}</td><td>${badge(participationState(s))}</td><td>${s.attempts}</td><td>${s.best_percentage===null?'—':s.best_percentage+'%'}</td></tr>`).join('')||'<tr><td colspan="6">No students match this filter.</td></tr>';}
function exportParticipation(){const safe=v=>{let s=String(v??'');if(/^\s*[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const rows=[['Examination','Student','Email','Account','Participation','Attempts','Best percentage'],...filteredParticipation().map(s=>[participation.exam.title,s.full_name,s.email,s.active?'Active':'Inactive',participationState(s),s.attempts,s.best_percentage])];const url=URL.createObjectURL(new Blob(['\ufeff'+rows.map(r=>r.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='ExamPortal-participation.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('input',e=>{if(e.target.id==='student-list-search'){clearTimeout(studentSearchTimer);studentSearchTimer=setTimeout(()=>loadStudents(e.target.value).catch(e=>toast(e.message,true)),250);}if(e.target.id==='enrollment-search'){clearTimeout(lookupTimer);lookupTimer=setTimeout(()=>enrollmentLookup(e.target.value).catch(e=>toast(e.message,true)),250);}if(e.target.id==='participation-search')filterParticipation();});
document.addEventListener('change',e=>{if(e.target.id==='participation-filter')filterParticipation();});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||busy||b.disabled)return;const action=b.dataset.action,n=Number(b.dataset.id);try{if(action==='new-class')classForm();else if(action==='edit-class')classForm(classList.find(c=>c.id===n));else if(action==='class-roster')await openRoster(n);else if(action==='back-classes')await navigate('classes');else if(action==='enroll-student')await enrollForm();else if(action==='audience')await audienceForm(n);else if(action==='participation')await openParticipation(n);else if(action==='export-participation')exportParticipation();else if(['delete-class','remove-student'].includes(action)){if(!confirm(action==='delete-class'?'Delete this class? Student accounts and results will be kept.':'Remove this student from the class? They cannot start new class-only attempts unless enrolled through another assigned class. Access to active attempts is blocked until the student rejoins with a valid code.'))return;busy=true;b.disabled=true;try{const d=await api(action==='delete-class'?`/classes/${n}`:`/classes/${roster.id}/students/${n}`,'DELETE');toast(d.message);if(action==='delete-class'){busy=false;await navigate('classes');}else await openRoster(roster.id);}finally{busy=false;b.disabled=false;}}}catch(e){toast(e.message,true);}});
document.addEventListener('submit',async e=>{if(!['class-form','enroll-form','audience-form'].includes(e.target.id))return;e.preventDefault();if(busy)return;const f=e.target,fd=new FormData(f),body=Object.fromEntries(fd),n=f.dataset.id,b=f.querySelector('button');busy=true;b.disabled=true;try{let d;if(f.id==='class-form'){d=await api('/classes'+(n?'/'+n:''),n?'PUT':'POST',body);$('modal').close();busy=false;await navigate('classes');}else if(f.id==='enroll-form'){d=await api(`/classes/${n}/students`,'POST',{student_id:Number(body.student_id)});$('modal').close();await openRoster(Number(n));}else{const only=body.class_only==='true';d=await api(`/exams/${n}/audience`,'PUT',{class_only:only,class_ids:only?fd.getAll('class_ids').map(Number):[]});$('modal').close();busy=false;await navigate('exams');}toast(d.message);}catch(e){if($('form-error'))$('form-error').textContent=e.message;else toast(e.message,true);}finally{busy=false;b.disabled=false;}});

let bankActive=false,bankPicker=false,bankExamId=null,bankRows=[],bankPage=1,bankPages=1,bankSelection=new Set(),bankRequest=0,bankSearchTimer;
function bankMetaFields(q={}){return `<div class="form-grid"><label>Subject / topic<input name="subject" maxlength="100" value="${esc(q.subject||'')}" placeholder="Web Development"></label><label>Difficulty<select name="difficulty">${['easy','medium','hard'].map(t=>`<option value="${t}" ${(q.difficulty||'medium')===t?'selected':''}>${t}</option>`).join('')}</select></label></div>`;}
async function openBank(picker=false){bankActive=true;bankPicker=picker;bankExamId=picker?questionExam.id:null;bankPage=1;bankSelection=new Set();$('breadcrumb').textContent='Workspace / Question bank';$('content').innerHTML=heading(picker?'Choose bank questions':'Question bank',picker?'Choose reusable questions to copy into your draft. Bank changes never alter existing exam copies.':'Store, organize, edit, and reuse questions across examinations.',picker?'<button class="primary" data-action="bank-import" id="bank-import">Add selected to draft (0)</button><button class="secondary" data-action="bank-back">← Question editor</button>':'<button class="primary" data-action="bank-new">+ Create bank question</button>')+`<div class="toolbar"><input type="search" id="bank-search" placeholder="Search question or subject…" aria-label="Search question bank"><input id="bank-subject" placeholder="Exact subject (optional)" aria-label="Filter by exact subject"><select id="bank-difficulty" aria-label="Filter difficulty"><option value="">All difficulties</option>${['easy','medium','hard'].map(t=>`<option>${t}</option>`).join('')}</select><select id="bank-type" aria-label="Filter question type"><option value="">All types</option>${typeOptions('')}</select></div><div class="actions"><button class="secondary" data-action="bank-prev" id="bank-prev">← Previous</button><span id="bank-page" class="muted"></span><button class="secondary" data-action="bank-next" id="bank-next">Next →</button>${picker?'<button class="secondary" data-action="bank-clear">Clear selection</button>':''}</div><section class="card table-wrap"><table><thead><tr>${picker?'<th>Select</th>':''}<th>Question</th><th>Subject</th><th>Type</th><th>Difficulty</th><th>Points</th><th></th></tr></thead><tbody id="bank-rows"></tbody></table></section><p class="note">Only your bank questions are listed; administrators can manage all bank questions. Each imported question is an independent copy. All four question types are supported.</p>`;await loadBank();}
async function loadBank(){const request=++bankRequest;if(!bankActive)return;const p=new URLSearchParams({page:bankPage,search:$('bank-search')?.value||'',subject:$('bank-subject')?.value||'',difficulty:$('bank-difficulty')?.value||'',type:$('bank-type')?.value||''});const d=await api('/bank?'+p);if(!bankActive||request!==bankRequest||!$('bank-rows'))return;bankRows=d.questions;bankPages=d.pages;if(bankPage>bankPages){bankPage=bankPages;await loadBank();return;}$('bank-page').textContent=`Page ${bankPage} / ${bankPages} · ${d.total} bank questions`;$('bank-prev').disabled=bankPage<=1;$('bank-next').disabled=bankPage>=bankPages;$('bank-rows').innerHTML=bankRows.map(q=>`<tr>${bankPicker?`<td><input type="checkbox" class="bank-select" data-bank-id="${q.id}" aria-label="Select question ${q.id}" ${bankSelection.has(q.id)?'checked':''}></td>`:''}<td><strong>${esc(q.prompt.slice(0,160))}</strong><small>#${q.id}</small></td><td>${esc(q.subject||'Uncategorized')}</td><td>${esc(typeLabels[qType(q)])}</td><td>${esc(q.difficulty)}</td><td>${q.points}</td><td><div class="actions"><button class="secondary" data-action="bank-preview" data-id="${q.id}">Preview</button>${!bankPicker?`<button class="secondary" data-action="bank-edit" data-id="${q.id}">Edit</button><button class="danger" data-action="bank-delete" data-id="${q.id}">Delete</button>`:''}</div></td></tr>`).join('')||`<tr><td colspan="${bankPicker?7:6}">No bank questions found. Create a bank question or use Save to bank in an exam's question editor.</td></tr>`;updateBankSelection();}
function updateBankSelection(){if($('bank-import')){$('bank-import').textContent=`Add selected to draft (${bankSelection.size})`;$('bank-import').disabled=!bankSelection.size;}}
function bankCopyForm(n){modal('Save reusable copy to bank',`<form id="bank-copy-form" data-id="${n}" data-exam="${questionExam.id}"><p class="note">This saves a separate reusable copy. The original exam question stays unchanged.</p>${bankMetaFields()}<button class="primary wide">Save to question bank</button><p class="error" id="form-error" role="alert"></p></form>`);}
document.addEventListener('input',e=>{if(['bank-search','bank-subject'].includes(e.target.id)){clearTimeout(bankSearchTimer);bankSearchTimer=setTimeout(()=>{bankPage=1;loadBank().catch(e=>toast(e.message,true));},250);}});
document.addEventListener('change',e=>{if(['bank-difficulty','bank-type'].includes(e.target.id)){bankPage=1;loadBank().catch(e=>toast(e.message,true));}if(e.target.dataset.bankId){const n=Number(e.target.dataset.bankId);if(e.target.checked)bankSelection.add(n);else bankSelection.delete(n);updateBankSelection();}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||busy||b.disabled)return;const action=b.dataset.action,n=Number(b.dataset.id);try{if(action==='bank-new')questionForm({},true);else if(action==='bank-edit')questionForm(bankRows.find(q=>q.id===n),true);else if(action==='bank-preview'){const q=bankRows.find(q=>q.id===n);modal('Bank question preview',`<p class="eyebrow">${esc(q.subject||'Uncategorized')} · ${esc(q.difficulty)} · ${q.points} points</p><h3>${esc(q.prompt)}</h3>${instructorKey(q)}`);}else if(action==='bank-copy')bankCopyForm(n);else if(action==='bank-pick')await openBank(true);else if(action==='bank-back'){bankActive=false;bankRequest++;await openQuestions(bankExamId);}else if(action==='bank-prev'||action==='bank-next'){bankPage+=action==='bank-next'?1:-1;await loadBank();}else if(action==='bank-clear'){bankSelection.clear();await loadBank();}else if(action==='bank-delete'||action==='bank-import'){if(action==='bank-delete'&&!confirm('Delete this bank question? Existing exam copies and saved attempts will be kept.'))return;busy=true;b.disabled=true;try{const d=await api(action==='bank-delete'?`/bank/${n}`:`/exams/${bankExamId}/from-bank`,action==='bank-delete'?'DELETE':'POST',{question_ids:[...bankSelection]});toast(d.message);if(action==='bank-delete')await loadBank();else{bankActive=false;bankRequest++;await openQuestions(bankExamId);}}finally{busy=false;b.disabled=false;}}}catch(e){toast(e.message,true);}});
document.addEventListener('submit',async e=>{if(!['bank-form','bank-copy-form'].includes(e.target.id))return;e.preventDefault();if(busy)return;const f=e.target,b=Object.fromEntries(new FormData(f)),n=f.dataset.id,button=f.querySelector('button');busy=true;button.disabled=true;try{let d;if(f.id==='bank-copy-form')d=await api(`/exams/${f.dataset.exam}/questions/${n}/to-bank`,'POST',b);else{const type=$('question-type').value,count=type==='true_false'?2:4;d=await api('/bank'+(n?'/'+n:''),n?'PUT':'POST',{...b,question_type:type,options:['identification','enumeration'].includes(type)?[]:Array.from({length:count},(_,i)=>b['option'+i]),accepted_answers:['identification','enumeration'].includes(type)?parseKey(b.key):[],correct_index:Number(b.correct_index),points:Number(b.points)});}$('modal').close();toast(d.message);if(bankActive)await loadBank();}catch(e){if($('form-error'))$('form-error').textContent=e.message;else toast(e.message,true);}finally{busy=false;button.disabled=false;}});

function updateRegistrationFields(){
 $('registration-role-field').hidden=!registering;$('registration-role').disabled=!registering;
}
$('registration-role').addEventListener('change',updateRegistrationFields);

document.addEventListener('click',async e=>{
 const b=e.target.closest('[data-action]');if(!b||busy||b.disabled)return;
 if(b.dataset.action==='join-class')modal('Join an instructor’s class',`<form id="join-class-form"><label>Class code<input name="code" required minlength="16" maxlength="16" autocomplete="off" placeholder="Code from your instructor"></label><p class="note">Joining enrolls your student account in this class. Published examinations assigned to it appear in Available Exams.</p><button class="primary wide">Join class</button><p id="form-error" class="error" role="alert"></p></form>`);
 if(b.dataset.action==='rotate-class-code'){
  if(!confirm('Generate a new class code? Any previous code will stop working. Current students stay enrolled.'))return;
  busy=true;b.disabled=true;try{const d=await api(`/classes/${b.dataset.id}/join-code`,'POST',{});busy=false;await navigate('classes');toast(d.message);}catch(e){toast(e.message,true);}finally{busy=false;b.disabled=false;}
 }
});
document.addEventListener('submit',async e=>{
 if(e.target.id!=='join-class-form')return;e.preventDefault();if(busy)return;
 const f=e.target,b=f.querySelector('button');busy=true;b.disabled=true;
 try{const d=await api('/classes/join','POST',Object.fromEntries(new FormData(f)));$('modal').close();busy=false;await navigate('classes');toast(d.message);}catch(e){$('form-error').textContent=e.message;}finally{busy=false;b.disabled=false;}
});

let resetEmail='',resetSending=false,resetResendUntil=0;
function passwordResetForm(email=''){
 modal('Forgot your password?',`<form id="password-forgot-form"><p class="muted">Enter your registered email. We’ll send a 6-digit code to reset your ExamPortal password.</p><label>Email address<input name="email" type="email" required maxlength="254" autocomplete="email" value="${esc(email)}"></label><button class="primary wide">Send reset code</button><p id="form-error" class="error" role="alert"></p></form>`);
 $('modal').querySelector('input').focus();
}
function passwordCodeForm(){
 modal('Reset your password',`<form id="password-reset-form"><p class="note">If your email matches an active account, check your inbox and spam folder. Codes expire after 10 minutes. Use the newest code.</p><p class="muted">Email: ${esc(resetEmail)}</p><label>Verification code<input name="code" required inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" autocomplete="one-time-code" placeholder="6-digit code"></label><label>New password<input name="new_password" type="password" required minlength="8" autocomplete="new-password"></label><label>Confirm new password<input name="confirm_password" type="password" required minlength="8" autocomplete="new-password"></label><button class="primary wide">Update password</button><p id="form-error" class="error" role="alert"></p></form><div class="actions"><button class="secondary" data-action="reset-resend">Resend code (60-second cooldown)</button><button class="secondary" data-action="reset-change-email">Change email</button></div>`);
 $('modal').querySelector('input').focus();
}
$('forgot-password').addEventListener('click',()=>{if(!resetSending)passwordResetForm($('email').value);});
document.addEventListener('click',async e=>{
 const b=e.target.closest('[data-action]');if(!b||busy||resetSending)return;
 if(b.dataset.action==='reset-change-email')passwordResetForm(resetEmail);
 if(b.dataset.action==='reset-resend'){
  if(Date.now()<resetResendUntil){toast('Please wait '+Math.ceil((resetResendUntil-Date.now())/1000)+' seconds before requesting another code.',true);return;}
  resetSending=true;busy=true;b.disabled=true;try{const d=await api('/password/forgot','POST',{email:resetEmail});resetResendUntil=Date.now()+60000;toast(d.message);}catch(e){toast(e.message,true);}finally{resetSending=false;busy=false;b.disabled=false;}
 }
});
document.addEventListener('submit',async e=>{
 if(!['password-forgot-form','password-reset-form'].includes(e.target.id))return;e.preventDefault();if(resetSending||busy)return;
 const f=e.target,body=Object.fromEntries(new FormData(f)),button=f.querySelector('button'),label=button.textContent;
 if(f.id==='password-reset-form'&&body.new_password!==body.confirm_password){$('form-error').textContent='Passwords do not match.';return;}
 resetSending=true;busy=true;button.disabled=true;button.textContent=f.id==='password-forgot-form'?'Sending code…':'Updating password…';
 try{
  if(f.id==='password-forgot-form'){const d=await api('/password/forgot','POST',body);resetEmail=body.email.trim().toLowerCase();resetResendUntil=Date.now()+60000;passwordCodeForm();toast(d.message);}
  else{const d=await api('/password/reset','POST',{...body,email:resetEmail});$('modal').close();$('modal-body').replaceChildren();$('auth-form').reset();$('email').value=resetEmail;$('password').focus();resetEmail='';toast(d.message);}
 }catch(e){if($('form-error'))$('form-error').textContent=e.message;else toast(e.message,true);}
 finally{resetSending=false;busy=false;button.disabled=false;button.textContent=label;}
});
